"Поставь своего защитника — и Капище перейдёт твоему клану.":"Tempatkan pembelamu — dan Kapishche jadi milik klanmu.",
"Поражение":"Kalah",
"«Приходи, когда окрепнешь», — говорит {0}. Попробуй другую команду: смотри на стихии хранителя и береги щиты для его приёмов.":"“Kembalilah saat kamu lebih kuat,” kata {0}. Coba tim lain: perhatikan elemen penjaga dan simpan perisai untuk jurusnya.",
"Хорошая тренировка! Награда за поединок с {0} сегодня уже получена.":"Latihan yang bagus! Hadiah duel dengan {0} hari ini sudah diambil.",
"{0} жмёт тебе руку: «Честный бой!» Дружба крепнет.":"{0} menjabat tanganmu: “Pertarungan yang jujur!” Pertemanan makin erat.",
"<b>+1 ★</b> дружбы":"<b>+1 ★</b> pertemanan",
"Духи {0} оказались сильнее. Подбери команду против их стихий и попробуй снова — поединки с другом не ограничены.":"Roh {0} lebih kuat. Susun tim yang unggul melawan elemen mereka dan coba lagi — duel dengan teman tak dibatasi.",
"Источник освобождён!":"Sumber bebas!",
"Прислужник растворился в тумане. Один из его духов — омрачённый {0} — остался рядом. Его ещё можно спасти!":"Antek itu lenyap dalam kabut. Salah satu rohnya — {0} tergelap — tertinggal di dekat sini. Dia masih bisa diselamatkan!",
