"Соперник — Ловчий с рейтингом ±{0} от твоего, а если такого нет — Ловчий Ордена. Рейтинг зависит от силы соперника · опыт — за первые {1} боёв дня":"Lawanmu adalah Pemburu dengan peringkat ±{0} dari peringkatmu, atau Pemburu Ordo jika tidak ada. Peringkat bergantung pada kekuatan lawan · XP untuk {1} pertarungan pertama hari ini",
