"Рейтинг зависит от соперника: победа над сильным даёт много, над слабым — мало; поражение от слабого стоит дороже. В твоей лиге победа над равным — +{0}, поражение — −{1}; чем выше лига, тем медленнее подъём. Из лиги можно выпасть. Награду за лигу дают один раз за сезон. В начале нового сезона рейтинг сверх {2} срезается наполовину, а за высшую лигу прошлого сезона Орден дарит сундук. В лигах «{3}», «{4}» и «{5}» — ещё и амулет.":"Rating tergantung lawan: menang atas yang kuat memberi banyak, atas yang lemah — sedikit; kalah dari yang lemah lebih mahal. Di ligamu, menang atas lawan setara +{0}, kalah −{1}; makin tinggi liga, makin lambat naiknya. Kamu bisa turun liga. Hadiah liga diberikan sekali per musim. Di awal musim baru rating di atas {2} dipotong separuh, dan untuk liga tertinggi musim lalu Ordo memberi peti. Di liga “{3}”, “{4}”, dan “{5}” — juga amulet.",
