"Бросай оберег, когда кольцо сжимается: «Отлично!» даёт больше опыта и шанс поимки.":"Lempar jimat saat cincin menyusut: “Hebat!” memberi XP dan peluang tangkap lebih besar.",
"Источники наполняются снова через несколько минут — прогулка по кругу приносит припасы.":"Sumber terisi lagi dalam beberapa menit — jalan memutar memberi perbekalan.",
"Спутник ходит с тобой и находит эссенцию своего семейства.":"Pendamping berjalan bersamamu dan menemukan esensi keluarganya.",
"В Лиге дерутся живые Ловчие: победа над сильным соперником даёт больше рейтинга, чем над слабым.":"Di Liga, Pemburu sungguhan bertarung: menang atas lawan kuat memberi rating lebih banyak daripada atas yang lemah.",
"Разломы открываются у Капищ каждый час: собери команду из трёх духов.":"Retakan terbuka di dekat Kapishche tiap jam: kumpulkan tim tiga roh.",
"Сияющие духи редки — их выдают искры вокруг.":"Roh berkilau itu langka — ciri khasnya percikan di sekitarnya.",
"Коконы греются шагами: одновременно можно греть три.":"Kepompong dihangatkan dengan langkah: bisa tiga sekaligus.",
"Ходи джойстиком: лёгкий наклон — шаг, до упора — бег. Километры для коконов считаются так же.":"Bergeraklah dengan joystick: miring sedikit untuk berjalan, penuh untuk berlari. Kilometernya tetap dihitung untuk kepompong.",
"Атлас мира переносит в любой уголок Земли раз в полчаса, а Врата Перепутицы — сразу.":"Atlas Dunia membawamu ke sudut Bumi mana pun tiap setengah jam — Gerbang Kekusutan Besar seketika.",
"Задания дня обновляются в полночь, а за все три ждёт Сундук дня.":"Misi harian diperbarui tengah malam, dan untuk ketiganya ada Peti Harian.",
"Поставь защитника на Капище своего клана — он принесёт искры.":"Tempatkan pembela di Kapishche klanmu — dia akan membawa percikan.",
"Погода усиливает духов своей стихии: в дождь чаще встречаются водные.":"Cuaca memperkuat roh elemennya: saat hujan roh air lebih sering muncul.",
