"Весь мир — твой":"Seluruh dunia milikmu",
"Перепутица спутала дороги мира, и Орден Оберега открыл Ловчим Врата: выбери в Атласе мира любой уголок Земли — там и начнёшь охоту. По карте ходи джойстиком, а в новые края шагай через Атлас. Настоящее местоположение телефона игре не нужно. Прогресс хранится на сервере игры и доступен только тебе; сервер проверяет каждое действие, поэтому нужен интернет. Места на карте и погода загружаются для выбранного района у OpenStreetMap и Open-Meteo (погоду можно выключить в настройках).":"Kekusutan Besar mengacaukan jalan-jalan dunia, dan Ordo Jimat membuka Gerbang bagi para Pemburu: pilih sudut Bumi mana pun di Atlas Dunia — di sanalah perburuanmu dimulai. Jelajahi peta dengan joystick, dan pergi ke negeri baru lewat Atlas. Game ini tidak butuh lokasi asli ponselmu. Progresmu disimpan di server game dan hanya bisa diakses olehmu; server memeriksa setiap tindakan, jadi perlu internet. Tempat di peta dan cuaca untuk area pilihanmu dimuat dari OpenStreetMap dan Open-Meteo (cuaca bisa dimatikan di pengaturan).",
